initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  let pageSize = 20;
  let filteredLogs = [];
  let allLogs = [];
  let autoUpdateInterval = null;

  // データ収集ログのテーブルインデックスを取得
  const logTableIndex = tables.findIndex(t => t.tableName === 'データ収集ログ');

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { class: 'status-success', text: '成功' },
      '失敗': { class: 'status-error', text: '失敗' },
      '警告': { class: 'status-warning', text: '警告' },
      '実行中': { class: 'status-running', text: '実行中' }
    };
    const statusInfo = statusMap[status] || { class: 'status-success', text: status };
    return `<span class="status-badge ${statusInfo.class}">${statusInfo.text}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // テーブル再描画関数
  function renderRows(logs) {
    const tbody = container.querySelector('#log-table-body');
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: var(--text-muted);">該当するログが見つかりません</td></tr>';
      return;
    }

    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageData = logs.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(log => `
      <tr class="log-row" data-id="${log.ログID || log.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 12px 16px; color: var(--text);">${(log.ログID || log.id || '').substring(0, 8)}...</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データ種別 || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データソース || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${formatDateTime(log.収集開始日時)}</td>
        <td style="padding: 12px 16px;">${getStatusBadge(log.処理ステータス || '成功')}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.収集件数 || 0}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.エラー件数 || 0}</td>
        <td style="padding: 12px 16px;">
          ${log.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${log.ログID || log.id}" style="margin-right: 8px; padding: 4px 8px; font-size: 12px;">再実行</button>` : ''}
          <button class="action-btn secondary detail-btn" data-id="${log.ログID || log.id}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(logs.length);
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    const totalPages = Math.ceil(totalCount / pageSize);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev-page');
    const nextBtn = container.querySelector('#btn-next-page');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // サマリー情報更新
  function updateSummary(logs) {
    const totalCount = logs.length;
    const successCount = logs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = logs.filter(log => log.処理ステータス === '失敗').length;
    const successRate = totalCount > 0 ? Math.round((successCount / totalCount) * 100) : 0;

    container.querySelector('#total-count').textContent = totalCount.toLocaleString();
    container.querySelector('#success-rate').textContent = `${successRate}%`;
    container.querySelector('#error-count').textContent = errorCount.toLocaleString();

    // システム状態の更新
    const statusLight = container.querySelector('#status-light');
    const statusText = container.querySelector('#status-text');

    if (errorCount > totalCount * 0.1) { // エラー率10%以上
      statusLight.style.background = '#ef4444';
      statusText.textContent = 'エラー';
    } else if (errorCount > 0) {
      statusLight.style.background = '#f59e0b';
      statusText.textContent = '警告';
    } else {
      statusLight.style.background = '#22c55e';
      statusText.textContent = '正常';
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日時バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日時は開始日時より後の日付を指定してください');
      return;
    }

    filteredLogs = allLogs.filter(log => {
      if (dataSource && log.データソース !== dataSource) return false;
      if (logLevel && !log.処理ステータス?.includes(logLevel)) return false;

      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate < new Date(startDate)) return false;
      }

      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate > new Date(endDate)) return false;
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
    updateSummary(filteredLogs);
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const headers = ['ログID', 'データ種別', 'データソース', '収集開始日時', '収集終了日時', '処理ステータス', '収集件数', 'エラー件数', 'エラーメッセージ'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredLogs.map(log => [
        `"${log.ログID || log.id || ''}"`,
        `"${log.データ種別 || ''}"`,
        `"${log.データソース || ''}"`,
        `"${formatDateTime(log.収集開始日時)}"`,
        `"${formatDateTime(log.収集終了日時)}"`,
        `"${log.処理ステータス || ''}"`,
        log.収集件数 || 0,
        log.エラー件数 || 0,
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ログ詳細表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => (l.ログID || l.id) === logId);
    if (!log) return;

    const modal = container.querySelector('#log-detail-modal');
    const content = container.querySelector('#log-detail-content');

    content.innerHTML = `
      <div style="display: grid; gap: 16px;">
        <div><strong>ログID:</strong> ${log.ログID || log.id || ''}</div>
        <div><strong>データ種別:</strong> ${log.データ種別 || ''}</div>
        <div><strong>データソース:</strong> ${log.データソース || ''}</div>
        <div><strong>店舗ID:</strong> ${log.店舗ID || ''}</div>
        <div><strong>収集開始日時:</strong> ${formatDateTime(log.収集開始日時)}</div>
        <div><strong>収集終了日時:</strong> ${formatDateTime(log.収集終了日時)}</div>
        <div><strong>処理ステータス:</strong> ${getStatusBadge(log.処理ステータス || '成功')}</div>
        <div><strong>対象期間:</strong> ${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
        <div><strong>収集件数:</strong> ${log.収集件数 || 0}件</div>
        <div><strong>エラー件数:</strong> ${log.エラー件数 || 0}件</div>
        <div><strong>処理時間:</strong> ${log.処理時間秒 || 0}秒</div>
        <div><strong>データ品質スコア:</strong> ${log.データ品質スコア || 0}/100</div>
        ${log.エラーメッセージ ? `<div><strong>エラーメッセージ:</strong><br><pre style="background: rgba(239, 68, 68, 0.1); padding: 12px; border-radius: 4px; white-space: pre-wrap; color: var(--text);">${log.エラーメッセージ}</pre></div>` : ''}
        ${log.備考 ? `<div><strong>備考:</strong> ${log.備考}</div>` : ''}
      </div>
    `;

    modal.style.display = 'block';
  }

  // 自動更新機能
  function toggleAutoUpdate() {
    const toggle = container.querySelector('#auto-update-toggle');
    if (toggle.checked) {
      autoUpdateInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(logTableIndex);
        if (logs) {
          allLogs = logs;
          applyFilters();
        }
      }, 30000); // 30秒間隔
    } else {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const logs = await window.aivicApi.list(logTableIndex);
    if (logs) {
      allLogs = logs;
      filteredLogs = logs;
      renderRows(filteredLogs);
      updateSummary(filteredLogs);
    } else {
      // APIが利用できない場合は初期データを使用
      allLogs = tables[logTableIndex]?.records || [];
      filteredLogs = allLogs;
      renderRows(filteredLogs);
      updateSummary(filteredLogs);
    }
  }

  // イベントリスナー設定

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // フィルタクリア
  container.querySelector('#btn-clear-filters').addEventListener('click', () => {
    container.querySelector('#filter-data-source').value = '';
    container.querySelector('#filter-log-level').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    filteredLogs = allLogs;
    currentPage = 1;
    renderRows(filteredLogs);
    updateSummary(filteredLogs);
  });

  // エクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportToCSV);

  // 自動更新トグル
  container.querySelector('#auto-update-toggle').addEventListener('change', toggleAutoUpdate);

  // アラート通知設定ボタン
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    alert('アラート通知設定画面を表示します（実装予定）');
  });

  // ページネーション
  container.querySelector('#btn-prev-page').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredLogs);
    }
  });

  container.querySelector('#btn-next-page').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredLogs.length / pageSize);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredLogs);
    }
  });

  container.querySelector('#page-size').addEventListener('change', (e) => {
    pageSize = parseInt(e.target.value);
    currentPage = 1;
    renderRows(filteredLogs);
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').style.display = 'none';
  });

  // テーブル行のクリックイベント（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    // ログ行クリックで詳細表示
    const logRow = e.target.closest('.log-row');
    if (logRow && !e.target.closest('button')) {
      const logId = logRow.dataset.id;
      showLogDetail(logId);
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      showLogDetail(logId);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('このログの処理を再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      // 実際の再実行処理はここで実装
      alert('再実行処理を開始しました');

      // ログを再読み込み
      setTimeout(async () => {
        const logs = await window.aivicApi.list(logTableIndex);
        if (logs) {
          allLogs = logs;
          applyFilters();
        }
      }, 1000);
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#log-detail-modal')) {
      container.querySelector('#log-detail-modal').style.display = 'none';
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}
